records.command:
cat > .local/smart-shorts-performance/probe.mjs <<'JS'
import{readFile,writeFile}from'node:fs/promises';import{spawn}from'node:child_process';
const mode=process.argv[2]??'commit';const p=JSON.parse(await readFile('.local/smart-shorts-audio/project-before.json','utf8'));const record=p.__opencutEditorSession,r=JSON.parse(record);const request=mode==='commit'?{type:'commit',sessionId:r.lease.sessionId,generation:r.generation,expectedStorageRevision:r.storageRevision,requestId:'isolated-performance-probe',bundle:r.saved.bundle}:{type:'acquire',sessionId:'isolated-performance',expectedGeneration:r.generation,takeOver:true};
const start=performance.now();const child=spawn('./target/release/opencut-session-policy',[],{stdio:['pipe','ignore','pipe']});await writeFile('.local/smart-shorts-performance/probe-pid.json',JSON.stringify({pid:child.pid,mode}));child.stderr.on('data',b=>process.stderr.write(b));child.stdin.end(JSON.stringify({record,accountId:r.accountId,projectId:r.projectId,request,nowMs:r.lastHostTimeMs}));child.on('close',async code=>{const result={mode,code,seconds:(performance.now()-start)/1000};console.log(result);await writeFile(`.local/smart-shorts-performance/${mode}-before.json`,JSON.stringify(result));});
JS
node .local/smart-shorts-performance/probe.mjs commit > .local/smart-shorts-performance/probe.log 2>&1
